		description: "A disabled multi-select combobox. Best for a locked multi value field holding 2 preset chips, disabled at the root rather than on the input.",
		file: "combobox-13",
		source:
			'"use client";\n\nimport {\n\tCombobox,\n\tComboboxChip,\n\tComboboxChips,\n\tComboboxChipsInput,\n\tComboboxCollection,\n\tComboboxContent,\n\tComboboxEmpty,\n\tComboboxItem,\n\tComboboxList,\n\tuseComboboxAnchor,\n} from "@workspace/ui/components/combobox";\nimport { Field } from "@workspace/ui/components/field";\nimport type * as React from "react";\nimport { useState } from "react";\n\nconst FRAMEWORKS: readonly string[] = ["Next.js", "SvelteKit", "Nuxt.js", "Remix", "Astro"];\n\n/** The frameworks picked when the example first renders. */\nconst INITIAL_FRAMEWORKS: readonly string[] = ["Next.js", "SvelteKit"];\n\nfunction renderFrameworkItem(framework: string): React.JSX.Element {\n\treturn (\n\t\t<ComboboxItem key={framework} value={framework}>\n\t\t\t{framework}\n\t\t</ComboboxItem>\n\t);\n}\n\nexport function Combobox13Example(): React.JSX.Element {\n\tconst anchor = useComboboxAnchor();\n\tconst [frameworks, setFrameworks] = useState<string[]>(() => [...INITIAL_FRAMEWORKS]);\n\n\treturn (\n\t\t<Field className="max-w-xs">\n\t\t\t<Combobox multiple autoHighlight items={FRAMEWORKS} value={frameworks} onValueChange={setFrameworks} disabled>\n\t\t\t\t<ComboboxChips ref={anchor}>\n\t\t\t\t\t{frameworks.map((framework: string): React.JSX.Element => (\n\t\t\t\t\t\t<ComboboxChip key={framework}>{framework}</ComboboxChip>\n\t\t\t\t\t))}\n\t\t\t\t\t<ComboboxChipsInput placeholder="Select frameworks..." />\n\t\t\t\t</ComboboxChips>\n\t\t\t\t<ComboboxContent anchor={anchor}>\n\t\t\t\t\t<ComboboxEmpty text="No items found." />\n\t\t\t\t\t<ComboboxList>\n\t\t\t\t\t\t<ComboboxCollection>{renderFrameworkItem}</ComboboxCollection>\n\t\t\t\t\t</ComboboxList>\n\t\t\t\t</ComboboxContent>\n\t\t\t</Combobox>\n\t\t</Field>\n\t);\n}\n',
